     for(PhotoCatalog.Asset asset:manifest.media.values()){interrupted();expectEntry(reader.next(),"media/"+asset.hash+".jpg");File target=new File(staging,token+"-"+asset.hash+".jpg");files.put(asset.hash,target);repository.exclusive(()->media.stageRestore(reader.zip,staging,token,asset));reader.zip.closeEntry();reader.verify("media/"+asset.hash+".jpg");}if(reader.next()!=null)throw new IOException("Unlisted backup entry");
